c.new(6, "F", "Quelle est l'unité de longueur du Système international ?", ["Le mètre", "Le pied", "Le pouce", "Le mille"], "Le mètre (m) est défini à partir de la distance parcourue par la lumière dans le vide pendant un très court instant.", PR, "C")
c.new(7, "M", "Quelle est l'unité de masse du Système international ?", ["Le kilogramme", "Le gramme", "La tonne", "Le newton"], "Le gramme et la tonne sont des sous-multiples ou multiples usuels, mais l'unité de base est le kilogramme (kg) ; le newton mesure une force.", "Larousse : kilogramme", "C")
c.new(8, "M", "Quelle est l'unité de temps du Système international ?", ["La seconde", "La minute", "L'heure", "Le jour"], "La minute et l'heure sont tolérées avec le SI, mais l'unité de base est la seconde (s).", PR, "C")
c.new(9, "M", "Quelle est l'unité de température du Système international ?", ["Le kelvin", "Le degré Celsius", "Le degré Fahrenheit", "Le joule"], "0 K correspond à − 273,15 °C ; une variation de 1 K vaut une variation de 1 °C.", "Larousse : kelvin", "C")
c.new(10, "M", "Quelle est l'unité de volume du Système international ?", ["Le mètre cube", "Le litre", "Le centimètre cube", "Le gramme"], "Le litre (1 dm³) est très employé mais n'est pas une unité du SI ; 1 m³ = 1 000 L.", PR, "C")
c.new(11, "F", "Combien de kilogrammes représentent 3 000 grammes ?", ["3 kg", "30 kg", "0,3 kg", "300 kg"], "1 kg = 1 000 g, donc 3 000 g = 3 kg.", PR + " (conversions)", "C")
c.base(1318, ex="1 km = 1 000 m, donc 5 km = 5 × 1 000 m = 5 000 m.", src="Base Q1318 (explication reprise)", typ="C")
