c.base(1317, en="Puissance de dix la plus proche d'une valeur, utilisée pour estimer sa taille", ch=["L'ordre de grandeur", "L'incertitude", "L'exactitude", "La précision"], ex="Le rayon de la Terre, 6,4 × 10⁶ m, est de l'ordre de 10⁷ m.", src="Base Q1317 (modifiée) — Programme A1 (pas de définition au Larousse en ligne)", typ="D")

