c.new(35, "M", "Grandeur entièrement définie par un nombre et son unité", ["Une grandeur scalaire", "Une grandeur vectorielle", "Une grandeur nulle", "Une grandeur variable"], "La masse, la température et le volume sont des grandeurs scalaires : aucune direction n'est nécessaire.", "Larousse : scalaire", "D")
c.new(36, "F", "Laquelle de ces grandeurs est vectorielle ?", ["La force", "La masse", "La température", "Le volume"], "Une force se décrit par son point d'application, sa direction, son sens et sa valeur.", PR + " / B1", "C")

c.groupe("La matière et ses états")
c.new(41, "F", "Substance qui constitue les corps et possède des propriétés physiques", ["La matière", "L'énergie", "La lumière", "L'espace"], "Tout ce qui a une masse et occupe un volume est de la matière : l'air, l'eau, le bois. La lumière n'en est pas.", "Larousse : matière (sens 1)", "D")
c.new(42, "F", "Corps qui garde sa forme propre et son volume propre", ["Un solide", "Un liquide", "Un gaz", "Un plasma"], "Les particules d'un solide sont serrées et ne bougent presque pas ; exemples : le fer, le bois, la glace.", "Larousse : solide (sens 1, adapté) — Programme A1", "D")
